import sys
from itertools import combinations

def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

PRIMES = [17, 53, 71]

def generate_possible_primes(s):
    for r in range(2, len(s)):
        for combination in combinations(s, r):
            possible_prime_str = ''.join(sorted(combination))
            num = int(''.join(possible_prime_str))
            if num in PRIMES:
                return possible_prime_str
    # The input contains all digits from 1 to 9 exactly once and we have already checked for all smaller combinations; thus, at least two of the input numbers need to be deleted to form a prime.
    # In order to form a prime, any two-digit combination should not contain both 1 and another odd number.
    even_numbers_idx = [i for i, x in enumerate(s) if int(x) % 2 == 0]
    possible_primes = []
    def check_index(r):
        nonlocal s
        idx_list = list(range(len(s)))
        chosen = []
        r_combination = combinations(idx_list, r)
        for combination in r_combination:
            temp_str = [s[i] for i in sorted(combination + even_numbers_idx)]
            if ''.join(possible_primes) not in sorted(temp_str):
                possible_primes.append(temp_str[0])
                chosen.append(combination)
        return len(chosen)

    r_list_to_check = list(range(len(s))) 
    while r_list_to_check:
        if check_index(r_list_to_check[-1]):
            r_list_to_check.pop(-1)
        else:
            break
    for prime in PRIMES:

        # In order to form a prime, the two numbers should be 7 and 9.
        prime_str = sorted([s[i] for i, x in enumerate(s) if int(x) in [j for j in [prime]]])
        if ''.join(possible_primes + prime_str[1:] ) == '-1':
            return '13' if prime == 17 else ''
    return '-1'

def solve():
    t = int(sys.stdin.readline())

    results = []

    for _ in range(t):
        s = sys.stdin.readline().rstrip()

        result = generate_possible_primes(s)

        results.append(result)

    for result in results:
        if result == -1: print('-1')
        else:  print(''.join(sorted(str(int(result)))))


