        if int(it[0])!=it[0]:
            return -1
        return bin_search((0,it[1]+1),ans)

def bin_search(bound,ans):
    while bound[0]!=bound[1]:
        mid=(bound[0]+bound[1])//2
        x=ans[mid][0]/ans[mid-1][0]
        if int(x)!=x:
            return mid+1
        elif ans[mid][0]<ans[mid-1][0]:
            return bin_search((mid,bound[1]),ans)
        else:
            return bin_search((bound[0],mid),ans)

