def solve():
    t = int(sys.stdin.readline())

    for _ in range(t):
        s = list(sys.stdin.readline().strip())
        n = len(s)

        result = []

        # Separate characters into two sets: one with counts of even numbers and one with odd counts.
        even_sets = []
        odd_sets = []
        count_dict = {}
        for char in s:
            if char not in count_dict:
                count_dict[char] = 0
            count_dict[char] += 1
        # Separate character frequency into two groups, which will be used to construct a palindrome string.
        for char, freq in count_dict.items():
            if freq & 1 == 0:  
                even_sets.append([char] * (freq // 2 * 2))
            else:
                odd_sets.append([char])

        # If we have an odd number of characters overall, put the middle one in a set by itself.
        if len(s) % 2 != 0:
            odd_sets.append([s[len(s) // 2]])

        # Use itertools to generate alternating sets of even and odd numbers for the palindrome constructor function.
        pairs = list(itertools.zip_longest(*[even_sets + [[]]] * (len(odd_sets))))

        for pair in pairs: 
            if any(item is not None for item in pair):  
                result += [''.join(x) for x in itertools.zip_longest(*(pair))]

        print(''.join(result))

