    def __init__(self):
        self.parent = {}
        self.rank = {}

    def find(self, x):
        if x in self.parent and self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, a, b):
        a, b = self.find(a), self.find(b)
        if a != b:
            if self.rank[a] < self.rank[b]:
