def solve():
    t = int(input())
    for _ in range(t):
        n = int(input())

        permutations = [[i + 1 for i in range(n)]]
        fixed_points = n
        current_permutation_index = 1

        while True:
            next_permutation_index = get_next_permutation_index(fixed_points, len(permutations))
            if next_permutation_index is None:
                break

            # Find the index to swap with
            for i in range(n - 1):
                if permutations[-1][i] != n - current_permutation_index + 1 and permutations[-1][n - i - 2] != n - current_permutation_index + 1:
                    swapping = [permutations[-1][i], permutations[-1][n - i - 2]]
                    new_last_element = permutations[-1][-1]

                    # Move the last element to its correct position
                    for j in range(n - 2, i, -1):
                        if permutations[-1][j] == n:
                            swapping.append(permutations[-1].pop())

                    permutations.append(swapping[::-1])
                    fixed_points -= 1
                    current_permutation_index += 1

                    # Break the loop as the new permutation is generated
                    break

            else:
                # If no swap was made, it means we've reached an invalid state.
                # So, we just append the identity permutation again
                permutations.append(permutations[-1])

        print(len(permutations))

        for line in permutations:
            print(" ".join(map(str, line)))

def get_next_permutation_index(fixed_points, length):
    if fixed_points == 0:
        return None

    for i in range(length - (fixed_points + 2)):
        if permutations[i][i] != permutations[i].count(permutations[i][i]):
            return i + 1
    return None

